        value={query}
        onChange={(e) => setQuery(e.target.value)}
        autoFocus
      />
      <ul className="results">
        {results.map((p) => (
          <li key={p._id}>
            <button className="result-row" onClick={() => onOpen(p._id)}>
              {p.name}
            </button>
          </li>
        ))}
      </ul>
      {trimmed !== "" && !hasExact && (
        <button
          className="add-button"
          onClick={async () => {
            const id = await addPerson({ name: trimmed });
            onOpen(id);
          }}
        >
          Add "{trimmed}"
        </button>
      )}
    </div>
  );
}

